struct Data {
    value: i32,
    label: String,
}

fn main() {
    let mut data = Data {
        value: 10,
        label: "initial".to_string(),
    };

    // Immutable borrow to read a field
    let v = data.value;
    let l = data.label.clone();

    // Mutable borrow to update a field
    data.value = 20;
    data.label = "updated".to_string();

    // Assert the updated value matches the expected integer
    assert_eq!(data.value, 20);

    println!("Ownership test passed");
}
